/**
 * Thermal Drift display LUT (GU47 WP-13 HS-12): one authored `.cube` for all three circuits, bound in the S10b display
 * grade by `effects.colorGrade({ lut, lutIntensity })` at a per-circuit strength (`CircuitLook.lutIntensity`). The file
 * `textures/luts/td-foundry.cube` is generated by `foundryLutCube()` below (pure, deterministic; the unit test checks the
 * committed file byte for byte), so the grade can be retuned in code and regenerated by writing `foundryLutCube()` to
 * that path (a two-line tsx script); `aura3d assets add --type lut` validation (`validateCubeLut`) passes: size 17,
 * 4913 rows.
 *
 * The look: a soft filmic S-curve, soot-and-iron shadows, molten-amber highlights. Coolant cyan stays cyan (the split
 * tone shifts it by a few code values only), so pickups and shields keep their one-colour role.
 */

/** Grid size (17^3 rows, 132 KB of text). */
export const FOUNDRY_LUT_SIZE = 17;

/** Display-space grade applied by the LUT (input and output in [0, 1]). */
export function foundryGrade(r: number, g: number, b: number): [number, number, number] {
  const l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const shadow = (1 - l) * (1 - l);
  const highlight = l * l;
  const curve = (c: number) => {
    const s = c * c * (3 - 2 * c);
    return c + (s - c) * 0.28;
  };
  const clamp = (v: number) => Math.min(1, Math.max(0, v));
  return [
    clamp(curve(r) + 0.022 * shadow + 0.045 * highlight),
    clamp(curve(g) + 0.004 * shadow + 0.012 * highlight),
    clamp(curve(b) - 0.014 * shadow - 0.04 * highlight)
  ];
}

/** The `.cube` text (red varies fastest, as the format requires). */
export function foundryLutCube(size = FOUNDRY_LUT_SIZE): string {
  const lines = [
    "TITLE \"Thermal Drift foundry\"",
    "# GU47 WP-13 HS-12, generated by apps/showcase-heatsink/src/lut.ts foundryLutCube(); authored, no third-party source",
    `LUT_3D_SIZE ${size}`,
    "DOMAIN_MIN 0.0 0.0 0.0",
    "DOMAIN_MAX 1.0 1.0 1.0"
  ];
  const n = size - 1;
  for (let bi = 0; bi < size; bi += 1) {
    for (let gi = 0; gi < size; gi += 1) {
      for (let ri = 0; ri < size; ri += 1) {
        const [r, g, b] = foundryGrade(ri / n, gi / n, bi / n);
        lines.push(`${r.toFixed(6)} ${g.toFixed(6)} ${b.toFixed(6)}`);
      }
    }
  }
  return `${lines.join("\n")}\n`;
}
